import { mkdirSync, writeFileSync } from 'node:fs'
import { expect, test, type Page } from '@playwright/test'
import { mathTextbookUnits } from '../src/data/textbook/math'

const units = mathTextbookUnits.filter(u => u.chapter?.chapterId === 'math-ch01-numbers-expressions')
const unit = (id: string) => units.find(u => u.unitId === 'math-numbers-expressions-' + id)!
const bridge1 = 'ここまでは、共通する式を一つのまとまりとして見たり'
const bridge2 = 'ここまでは、平方根の積や商を計算し'
const root = 'e2e-evidence/wmath027'
const route = (path: string) => '/kyotsu-step-web/#' + path
const ids = ['numbers-polynomials', 'numbers-real', 'numbers-inequalities']
async function fits(page: Page) {
  await expect(page.locator('.katex-error')).toHaveCount(0)
  const widths = await page.evaluate(() => [document.documentElement.clientWidth, document.documentElement.scrollWidth])
  expect(widths[1]).toBeLessThanOrEqual(widths[0] + 1)
}
async function setup(page: Page) {
  await page.goto(route('/learning/setup?subject=math-1a'))
  await expect(page.getByTestId('math-textbook-chapter-1')).toBeVisible()
}
async function seed(page: Page, complete: string[], partial: string[]) {
  await page.evaluate(({ all, completeIds, partialIds }) => {
    const raw = JSON.parse(localStorage.getItem('kyotsu-step-store') || '{}')
    raw.state ??= {}; raw.state.textbookProgress ??= {}
    for (const u of all) {
      const items = u.sections.flatMap(s => s.items)
      if (!completeIds.includes(u.unitId) && !partialIds.includes(u.unitId)) continue
      const selected = completeIds.includes(u.unitId) ? items : items.slice(0, 1)
      const answers = Object.fromEntries(selected.map(q => [q.id, {
        itemId: q.id, value: q.answer, firstValue: q.answer, isFirstCorrect: true,
        resolved: true, attemptCount: 1, firstAnsweredAt: 1720000000000, lastAnsweredAt: 1720000000000,
      }]))
      raw.state.textbookProgress[u.unitId] = {
        unitId: u.unitId, unitRevision: u.revision, startedAt: 1720000000000,
        updatedAt: 1720000000000, answers,
        ...(completeIds.includes(u.unitId) ? { completedAt: 1720000000001 } : {}),
      }
    }
    localStorage.setItem('kyotsu-step-store', JSON.stringify(raw))
  }, { all: units, completeIds: complete.map(x => unit(x).unitId), partialIds: partial.map(x => unit(x).unitId) })
  await page.reload()
}
for (const width of [320, 390, 1440]) {
  test('W027 three cards and two actual bridge paragraphs ' + width, async ({ page }, info) => {
    test.skip(width === 1440 ? info.project.name !== 'desktop-chromium' : info.project.name !== 'mobile-chromium')
    await page.setViewportSize({ width, height: 1000 })
    mkdirSync(root, { recursive: true })
    await setup(page)
    await page.evaluate(() => localStorage.clear()); await page.reload()
    const chapter = page.getByTestId('math-textbook-chapter-1')
    const links = chapter.locator('a[data-testid^="math-textbook-topic-"]')
    await expect(links).toHaveCount(3)
    const labels = ['式を整える', '実数を扱う', '不等式を使う']
    for (let i = 0; i < 3; i++) {
      await expect(links.nth(i)).toHaveAttribute('data-testid', 'math-textbook-topic-' + ids[i])
      await expect(links.nth(i)).toContainText(labels[i])
      await expect(links.nth(i)).toContainText('0/' + [125, 77, 116][i] + ' 完了')
    }
    await expect(page.getByTestId('math-textbook-topic-numbers-development')).toHaveCount(0)
    await fits(page)
    await links.first().evaluate(el => {
      const top = window.scrollY + el.getBoundingClientRect().top - 150
      window.scrollTo({ top, behavior: 'instant' })
    })
    const blockers = await links.evaluateAll(nodes => nodes.flatMap(node => {
      const r = node.getBoundingClientRect()
      return Array.from(document.querySelectorAll('nav')).filter(nav => {
        const b = nav.getBoundingClientRect()
        return getComputedStyle(nav).position === 'fixed' && Math.min(r.right, b.right) > Math.max(r.left, b.left) + 1 && Math.min(r.bottom, b.bottom) > Math.max(r.top, b.top) + 1
      }).map(() => node.getAttribute('data-testid'))
    }))
    expect(blockers, 'fixed navigation must not cover any of the three captured cards').toEqual([])
    for (const card of await links.all()) await expect(card).toBeInViewport({ ratio: 1 })
    await page.screenshot({ path: `${root}/catalog-${width}.png` })
    for (const [code, title, bridge] of [['ne01', labels[0], bridge1], ['ne02', labels[1], bridge2]]) {
      await page.goto(route('/learning/textbook/' + unit(code).unitId))
      await expect(page.getByRole('heading', { level: 1 })).toHaveText(title)
      const paragraph = page.getByTestId('textbook-reading-flow').locator('p').filter({ hasText: bridge }).first()
      await expect(paragraph).toBeVisible()
      await expect(page.getByTestId('textbook-item-' + code + '-01')).toBeVisible()
      await fits(page)
      await page.screenshot({ path: `${root}/${code}-bridge-${width}.png`, fullPage: true })
    }
    writeFileSync(`${root}/screens-${width}.json`, JSON.stringify({ source: process.env.CAPTURE_SHA, width, titleCount: 3, screenshots: ['catalog', 'ne01-bridge', 'ne02-bridge'] }, null, 2))
  })
}
test('W027 saved answers survive regrouping, resume each development unit and preserve history', async ({ page }) => {
  await setup(page); await page.evaluate(() => localStorage.clear()); await page.reload()
  const completed = ['n01', 'n02', 'n03', 'n04', 'n05', 'n06', 'n07', 'n08', 'n09', 'n10']
  await seed(page, completed, ['ne01', 'ne02'])
  const before = await page.evaluate(() => JSON.parse(localStorage.getItem('kyotsu-step-store')!).state.textbookProgress)
  await expect(page.getByTestId('math-textbook-topic-numbers-polynomials')).toContainText('113/125 完了')
  await expect(page.getByTestId('math-textbook-topic-numbers-real')).toContainText('66/77 完了')
  for (const [topic, code] of [[ids[0], 'ne01'], [ids[1], 'ne02']]) {
    await expect(page.getByTestId('math-textbook-topic-' + topic)).toHaveAttribute('href', '#/learning/textbook/' + unit(code).unitId)
    await page.getByTestId('math-textbook-topic-' + topic).click()
    await expect(page.getByTestId('resolved-' + code + '-01')).toBeVisible()
    await setup(page)
  }
  for (const [from, to] of [['n06', 'ne01'], ['n10', 'ne02']]) {
    await page.goto(route('/learning/textbook/' + unit(from).unitId))
    await expect(page.getByTestId('textbook-next-unit')).toHaveAttribute('href', '#/learning/textbook/' + unit(to).unitId)
  }
  const after = await page.evaluate(() => JSON.parse(localStorage.getItem('kyotsu-step-store')!).state.textbookProgress)
  expect(after).toEqual(before)
  await setup(page); await seed(page, ['ne01', 'ne02'], [])
  const fullySaved = await page.evaluate(() => JSON.parse(localStorage.getItem('kyotsu-step-store')!).state.textbookProgress)
  await expect(page.getByTestId('math-textbook-topic-numbers-polynomials')).toContainText('122/122 完了')
  await expect(page.getByTestId('math-textbook-topic-numbers-real')).toContainText('77/77 完了')
  for (const code of ['ne01', 'ne02']) {
    await page.goto(route('/learning/textbook/' + unit(code).unitId))
    await expect(page.getByTestId('textbook-next-unit')).toHaveCount(0)
    await expect(page.getByTestId('textbook-return-to-setup')).toHaveAttribute('href', '#/learning/setup?subject=math-1a')
  }
  await page.reload()
  expect(await page.evaluate(() => JSON.parse(localStorage.getItem('kyotsu-step-store')!).state.textbookProgress)).toEqual(fullySaved)
})

const oldN02 = ['3bx', 'x^3-ax^2+3bx+5c', '(2y-3,\\ y^2-3y+2)', 'x^2+(2y-3)x+(y^2-3y+2)', '0x',
  'x^3-x^2+x+1', 'x^3-2x^2-2', '3x^3-5x^2+x-3',
  '(4x^3-6x^2+2x-2,\\ 3x^3-6x^2-6)', '7x^3-12x^2+2x-8', '2A-3B', '7x^3-12x^2+2x-8']
for (const width of [320, 390, 1440]) {
  test('N02 R1 approved local derivation, old history, wrong/hint/reload and real screens ' + width, async ({ page }, info) => {
    test.skip(width === 1440 ? info.project.name !== 'desktop-chromium' : info.project.name !== 'mobile-chromium')
    await page.setViewportSize({ width, height: 1000 })
    await setup(page)
    await page.evaluate(() => localStorage.clear()); await page.reload()
    const legacy = {
      unitId: unit('n02').unitId, unitRevision: 1, startedAt: 100, updatedAt: 200, completedAt: 199,
      answers: Object.fromEntries(oldN02.map((value, i) => {
        const itemId = 'n02-' + String(i + 1).padStart(2, '0')
        return [itemId, { itemId, value, firstValue: value, isFirstCorrect: true, resolved: true,
          attemptCount: 1, firstAnsweredAt: 110, lastAnsweredAt: 190 }]
      })),
    }
    await page.evaluate(old => {
      const raw = JSON.parse(localStorage.getItem('kyotsu-step-store') || '{}')
      raw.state ??= {}; raw.state.textbookProgress ??= {}
      raw.state.textbookProgress[old.unitId] = old
      localStorage.setItem('kyotsu-step-store', JSON.stringify(raw))
    }, legacy)
    await page.goto(route('/learning/textbook/' + unit('n02').unitId))
    await expect(page.getByTestId('resolved-n02-05')).toBeVisible()
    await expect(page.getByTestId('textbook-item-n02-06')).toBeVisible()
    await expect(page.getByTestId('textbook-item-n02-r2-q07-x3')).toHaveCount(0)
    const snapshots: string[] = []
    const captures: Record<string, string> = {
      'n02-r2-q09-a2': 'two-a', 'n02-09': 'minus-three-b',
      'n02-10': 'collect', 'n02-r2-q11-sign': 'bracket-sign',
    }
    for (const q of unit('n02').sections[0].items.slice(5)) {
      if (q.id === 'n02-12') continue // unchanged v1 Q12 stays resolved but cannot bypass new prerequisites
      const trigger = page.getByTestId('textbook-item-' + q.id)
      await expect(trigger).toBeVisible()
      const chain = trigger.locator('xpath=ancestor::div[contains(@class,"reading-derivation-chain")]')
      await expect(chain).toHaveCount(1)
      if (captures[q.id]) {
        await trigger.evaluate(el => window.scrollTo({ top: window.scrollY + el.getBoundingClientRect().top - 600, behavior: 'instant' }))
        await expect(trigger).toBeInViewport({ ratio: 1 })
        const overlap = await trigger.evaluate(el => {
          const a = el.getBoundingClientRect()
          return [...document.querySelectorAll('nav,header')].some(n => {
            const b = n.getBoundingClientRect()
            return ['fixed', 'sticky'].includes(getComputedStyle(n).position)
              && Math.min(a.right, b.right) > Math.max(a.left, b.left)
              && Math.min(a.bottom, b.bottom) > Math.max(a.top, b.top)
          })
        })
        expect(overlap).toBe(false)
        await fits(page)
        const dir = 'e2e-evidence/wmath027-n02'
        mkdirSync(dir, { recursive: true })
        const name = captures[q.id] + '-' + width + '.png'
        await page.screenshot({ path: dir + '/' + name })
        snapshots.push(name)
      }
      await trigger.click()
      let panel = page.getByTestId('inline-choice-panel-' + q.id)
      const options = await panel.getByRole('button').all()
      let wrongButton = options[0]
      for (const option of options) {
        if (await option.getAttribute('aria-label') !== q.answer) { wrongButton = option; break }
      }
      await wrongButton.click()
      await expect(trigger).toBeVisible()
      await trigger.click()
      panel = page.getByTestId('inline-choice-panel-' + q.id)
      await expect(page.getByTestId('textbook-hint-' + q.id)).toBeVisible()
      await page.reload()
      await expect(page.getByTestId('textbook-item-' + q.id)).toBeVisible()
      await page.getByTestId('textbook-item-' + q.id).click()
      await page.getByTestId('inline-choice-panel-' + q.id).getByRole('button', { name: q.answer, exact: true }).click()
      await expect(page.getByTestId('resolved-' + q.id)).toBeVisible()
    }
    await expect(page.getByTestId('textbook-unit-complete')).toBeVisible()
    await fits(page)
    await page.reload()
    await expect(page.getByTestId('textbook-unit-complete')).toBeVisible()
    const current = await page.evaluate(id => JSON.parse(localStorage.getItem('kyotsu-step-store')!).state.textbookProgress[id], unit('n02').unitId)
    expect(current.unitRevision).toBe(2)
    expect(current.archivedRevisions['1']).toEqual({ unitRevision: 1, startedAt: 100, updatedAt: 200, completedAt: 199, answers: legacy.answers })
    expect(current.answers['n02-05']).toEqual(legacy.answers['n02-05'])
    expect(current.answers['n02-09'].value).toBe('3')
    expect(current.answers['n02-09'].attemptCount).toBe(2)
    expect(current.answers['n02-12']).toEqual(legacy.answers['n02-12'])
    writeFileSync('e2e-evidence/wmath027-n02/screens-' + width + '.json', JSON.stringify({ source: process.env.CAPTURE_SHA, width, snapshots, legacyPreserved: true }, null, 2))
  })
}

import { describe, expect, it } from 'vitest'
import { mathSetUnit } from './set/setLesson'
import { mathNumbersReviewUnitIds, mathTextbookNextUnitId, mathTextbookTopicForUnit, mathTextbookTopicHasAllUnits, mathTextbookTopics } from './mathCatalog'
import { mathTextbookUnits } from './index'
import { textbookRepository } from '../../../repositories/textbookRepository'

describe('math textbook catalog', () => {
  it('aligns the set lesson with the overlapping practice curriculum without driving learner structure', () => {
    const topic = mathTextbookTopicForUnit(mathSetUnit.unitId)
    expect(topic?.id).toBe('organize-sets')
    expect(topic?.practiceLinks).toEqual([
      {
        topicId: 'organize-sets',
        questionNumbers: [87, 88, 89, 90, 91, 92, 93, 94, 95, 96, 97],
      },
    ])
    expect(topic?.flow.ja).toBe('集合の表し方 → 共通部分・和集合 → 部分集合 → 補集合 → 集合の条件')
  })


  it('keeps the three learning topics synchronized only where textbook content overlaps practice', () => {
    expect(mathTextbookTopics.map((topic) => topic.id)).toEqual([
      'numbers-polynomials',
      'numbers-real',
      'numbers-inequalities',
      'organize-sets',
      'read-propositions',
      'prove-propositions',
    ])
    expect(mathTextbookTopicForUnit('math-sets')?.unitIds).toEqual(['math-sets'])
    expect(mathTextbookTopicForUnit('math-propositions-reading')?.unitIds).toEqual(['math-propositions-reading', 'math-quantifiers-all-exists'])
    expect(mathTextbookTopicForUnit('math-propositions-proof')?.unitIds).toEqual(['math-propositions-proof'])
  })


  it('requires every configured unit before a multi-unit learner topic can open', () => {
    expect(mathTextbookTopicHasAllUnits('organize-sets', ['math-sets'])).toBe(true)
    expect(mathTextbookTopicHasAllUnits('read-propositions', ['math-propositions-reading'])).toBe(false)
    expect(
      mathTextbookTopicHasAllUnits('read-propositions', [
        'math-propositions-reading',
        'math-quantifiers-all-exists',
      ]),
    ).toBe(true)
  })

  it('keeps continuation inside a multi-unit learner topic', () => {
    expect(mathTextbookNextUnitId('math-propositions-reading')).toBe('math-quantifiers-all-exists')
    expect(mathTextbookNextUnitId('math-quantifiers-all-exists')).toBeUndefined()
    expect(mathTextbookNextUnitId('math-propositions-proof')).toBeUndefined()
  })

  it('keeps practice synchronization metadata internal without forcing practice taxonomy onto learner topics', () => {
    expect(mathTextbookTopicForUnit('math-propositions-reading')?.practiceLinks).toEqual([
      {
        topicId: 'read-propositions',
        questionNumbers: [98, 99, 100, 101, 102, 103, 104, 105, 106, 107, 109],
      },
    ])
    expect(mathTextbookTopicForUnit('math-propositions-proof')?.practiceLinks).toEqual([
      {
        topicId: 'prove-propositions',
        questionNumbers: [108, 110, 111, 112, 113, 114, 115, 116, 117],
      },
    ])

    const all = mathTextbookTopics.flatMap((topic) =>
      topic.practiceLinks.flatMap((link) => link.questionNumbers),
    )
    expect(new Set(all).size).toBe(all.length)
    expect([...all].sort((a, b) => a - b)).toEqual(
      Array.from({ length: 31 }, (_, index) => 87 + index),
    )
    expect(all).not.toContain(118)
    expect(all).not.toContain(119)
    expect(all).not.toContain(120)
    expect(mathTextbookTopicForUnit('math-functions-conditions')).toBeUndefined()
  })





  it('keeps chapter 3 units in textbook page order', () => {
    const chapter3 = mathTextbookUnits
      .filter((unit) => unit.chapter?.chapterNumber === '3')
      .map((unit) => [unit.unitId, unit.chapter?.orderInChapter])

    expect(chapter3).toEqual([
      ['math-sets', 1],
      ['math-propositions-reading', 2],
      ['math-propositions-proof', 3],
      ['math-quantifiers-all-exists', 4],
    ])
  })

  it('keeps current learner topics inside chapter 3 and leaves the function review in chapter 2', () => {
    const chapter3UnitIds = mathTextbookTopics.filter((topic) => topic.chapterId === 'math-ch03-sets-propositions').flatMap((topic) => topic.unitIds)
    for (const unitId of chapter3UnitIds) {
      expect(
        mathTextbookUnits.find((unit) => unit.unitId === unitId)?.chapter?.chapterNumber,
        unitId,
      ).toBe('3')
    }

    const functionUnit = mathTextbookUnits.find((unit) => unit.unitId === 'math-functions-conditions')
    expect(functionUnit?.chapter?.chapterNumber).toBe('2')
    expect(mathTextbookTopicForUnit('math-functions-conditions')).toBeUndefined()
  })

  it('keeps learner-facing topic flows aligned with the approved source-backed curriculum', () => {
    expect(mathTextbookTopicForUnit('math-propositions-reading')?.flow.ja).toBe(
      '真偽 → 必要条件・十分条件 → 条件の否定 → 「すべて」と「ある」',
    )
    expect(mathTextbookTopicForUnit('math-propositions-proof')?.flow.ja).toBe(
      '逆・裏・対偶 → 証明しやすい向き → 対偶による証明 → 矛盾を使う証明',
    )
  })

  it('keeps only the approved set lesson published while all unaccepted math pilots remain review-only', () => {
    expect(
      mathTextbookUnits.filter((unit) => unit.status === 'published').map((unit) => unit.unitId),
    ).toEqual(['math-sets'])

    expect(
      mathTextbookUnits.filter((unit) => unit.status === 'review').map((unit) => unit.unitId),
    ).toEqual([
      'math-numbers-expressions-n01',
      'math-numbers-expressions-n02',
      'math-numbers-expressions-n03',
      'math-numbers-expressions-n04',
      'math-numbers-expressions-n05',
      'math-numbers-expressions-n06',
      'math-numbers-expressions-n07',
      'math-numbers-expressions-n08',
      'math-numbers-expressions-n09',
      'math-numbers-expressions-n10',
      'math-numbers-expressions-n11',
      'math-numbers-expressions-n12',
      'math-numbers-expressions-n13',
      'math-numbers-expressions-n14',
      'math-numbers-expressions-ne01',
      'math-numbers-expressions-ne02',
      'math-propositions-reading',
      'math-propositions-proof',
      'math-quantifiers-all-exists',
      'math-functions-conditions',
    ])
  })

  it('keeps the approved three learner-facing headings in order', () => {
    const topic = mathTextbookTopicForUnit('math-sets')
    expect(topic?.learnerHeadings).toEqual([
      '第1部　集合を表す',
      '第2部　集合どうしの関係を見る',
      '第3部　集合の外側まで考える',
    ])

    const headings = mathSetUnit.sections[0].readingFlow
      .filter((block) => block.type === 'heading')
      .map((block) => block.text)

    expect(headings).toEqual(topic?.learnerHeadings)
  })

  it('keeps all sixteen chapter-1 lessons under exactly three approved learner topics', () => {
    const chapter1 = mathTextbookTopics.filter((topic) => topic.chapterId === 'math-ch01-numbers-expressions')
    expect(chapter1.map((topic) => topic.label.ja)).toEqual(['式を整える', '実数を扱う', '不等式を使う'])
    expect(chapter1.map((topic) => topic.unitIds.map((id) => id.replace('math-numbers-expressions-', '')))).toEqual([
      ['n01', 'n02', 'n03', 'n04', 'n05', 'n06', 'ne01'], ['n07', 'n08', 'n09', 'n10', 'ne02'], ['n11', 'n12', 'n13', 'n14'],
    ])
    const assigned = chapter1.flatMap((topic) => topic.unitIds)
    expect(assigned).toHaveLength(16)
    expect(new Set(assigned).size).toBe(16)
    expect(chapter1.map((topic) => topic.unitIds.reduce((total, id) => {
      const unit = mathTextbookUnits.find((candidate) => candidate.unitId === id)
      return total + (unit?.sections.reduce((count, section) => count + section.items.length, 0) ?? 0)
    }, 0))).toEqual([125, 77, 116])
    expect(mathTextbookNextUnitId('math-numbers-expressions-n06')).toBe('math-numbers-expressions-ne01')
    expect(mathTextbookNextUnitId('math-numbers-expressions-n10')).toBe('math-numbers-expressions-ne02')
    expect(mathTextbookNextUnitId('math-numbers-expressions-ne01')).toBeUndefined()
    expect(mathTextbookNextUnitId('math-numbers-expressions-ne02')).toBeUndefined()
    expect(mathNumbersReviewUnitIds).toHaveLength(16)
    for (const id of mathNumbersReviewUnitIds) {
      const unit = mathTextbookUnits.find((candidate) => candidate.unitId === id)
      expect(unit?.status, id).toBe('review')
      expect(unit?.chapter?.chapterId, id).toBe('math-ch01-numbers-expressions')
    }
    expect(mathTextbookNextUnitId('math-numbers-expressions-n01')).toBe('math-numbers-expressions-n02')
    expect(mathTextbookNextUnitId('math-numbers-expressions-n02')).toBe('math-numbers-expressions-n03')
    expect(mathTextbookNextUnitId('math-numbers-expressions-n09')).toBe('math-numbers-expressions-n10')
    expect(mathTextbookNextUnitId('math-numbers-expressions-n03')).toBe('math-numbers-expressions-n04')
    expect(mathTextbookNextUnitId('math-numbers-expressions-n14')).toBeUndefined()
  })

  it('exposes ONLY chapter-1 review previews in the learner setup, without promoting their published status', async () => {
    const published = await textbookRepository.listPublished()
    const visible = await textbookRepository.listLearningSetup()
    const publishedIds = published.map((unit) => unit.unitId)
    const visibleIds = visible.map((unit) => unit.unitId)
    expect(publishedIds).toContain('math-sets')
    for (const id of mathNumbersReviewUnitIds) {
      expect(publishedIds).not.toContain(id)
      expect(visibleIds).toContain(id)
    }
    for (const id of ['math-propositions-reading', 'math-propositions-proof', 'math-quantifiers-all-exists', 'math-functions-conditions']) {
      expect(visibleIds).not.toContain(id)
    }
  })
})

import { validateTextbookUnits } from '../../../../domain/textbookSchema'
import { T, M, C, K, reviewItem as item, oneToOneSourceMap } from './reviewLessonHelpers'

// W-MATH-003/P-001: user-accepted N02 exact learner-design review.
// Teacher-edited original Word N02 Q1–Q12, pp.4–5, original SHA 93827322...
// Solutions independently derived; separate official answer booklet not supplied.
// W-MATH-027/P-002-N02-R1: 12 original questions, 15 locally staged actions.
// Q01-Q05 and Q12 retain their accepted answer semantics; v1 is archived for re-keyed Q06-Q11.
export const n02SourceToItemIds = {
  ...oneToOneSourceMap('N02', 12),
  'N02-Q07': ['n02-r2-q07-x3', 'n02-07'],
  'N02-Q09': ['n02-r2-q09-a2', 'n02-09'],
  'N02-Q11': ['n02-r2-q11-sign', 'n02-11'],
} as const

const rawN02 = {
  schemaVersion: '1.1' as const,
  unitId: 'math-numbers-expressions-n02',
  revision: 2, status: 'review' as const, subject: 'math-1a' as const,
  chapter: {
